// Se saca el token y se guarda el cuerpo para despues.
const cab = $json.headers || {};
const auth = String(cab.authorization || cab.Authorization || '');
const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';

return [{ json: {
  token,
  hay_cabecera: auth.length > 0,
  body: $json.body || {},
} }];

// Supabase es la autoridad. Comprobado empiricamente:
//   token real           -> 200 + el usuario
//   token inventado      -> 403
//   sin token            -> 403
//   exp manipulado       -> 403  (cambiar el payload rompe la firma)

const r = $json || {};
const codigo = r.statusCode || 0;
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }

const previo = $('Sacar el token').first().json;

let valido = false;
let motivo = "";

if (!previo.hay_cabecera) {
  motivo = "falta la cabecera Authorization";
} else if (!previo.token) {
  motivo = "la cabecera no es del tipo Bearer";
} else if (codigo !== 200) {
  motivo = "sesión no válida o caducada (Supabase devolvió " + codigo + ")";
} else if (!cuerpo || !cuerpo.id) {
  motivo = "Supabase respondió 200 pero sin usuario";
} else if (cuerpo.role !== 'authenticated') {
  motivo = "el usuario no tiene rol authenticated";
} else {
  valido = true;
}

return [{ json: {
  veredicto: valido ? 'ok' : 'no',
  motivo,
  usuario_id: (cuerpo && cuerpo.id) || null,
  usuario_email: (cuerpo && cuerpo.email) || null,
  body: previo.body,
} }];

// capi_tomar() devuelve SOLO las lineas que acaba de tomar. Cero filas no
// es un error: o ya se reporto, o no hay nada validado nuevo. Se sale en
// 200 y en silencio, que es lo que pasa cuando validas dos veces seguidas.
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const lineas = Array.isArray(c) ? c : [];
const conv = $('Sacar el token').first().json.body.conversacion_id;
return [{ json: {
  conversacion_id: conv,
  lineas,
  hay: lineas.length ? 'si' : 'no',
  ids: lineas.map(function (l) { return l.id; }),
} }];

// SHA-256 en JavaScript puro: n8n bloquea el módulo 'crypto'
function sha256(msg) {
  function rotr(n,x){return (x>>>n)|(x<<(32-n));}
  function ch(x,y,z){return (x&y)^(~x&z);}
  function maj(x,y,z){return (x&y)^(x&z)^(y&z);}
  function s0(x){return rotr(2,x)^rotr(13,x)^rotr(22,x);}
  function s1(x){return rotr(6,x)^rotr(11,x)^rotr(25,x);}
  function g0(x){return rotr(7,x)^rotr(18,x)^(x>>>3);}
  function g1(x){return rotr(17,x)^rotr(19,x)^(x>>>10);}
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bytes=[];
  for(const cp of unescape(encodeURIComponent(msg))) bytes.push(cp.charCodeAt(0));
  const bitLen=bytes.length*8;
  bytes.push(0x80);
  while(bytes.length%64!==56) bytes.push(0);
  for(let i=7;i>=0;i--) bytes.push((bitLen/Math.pow(2,i*8))&0xff);
  for(let b=0;b<bytes.length;b+=64){
    const w=new Array(64);
    for(let i=0;i<16;i++) w[i]=(bytes[b+i*4]<<24)|(bytes[b+i*4+1]<<16)|(bytes[b+i*4+2]<<8)|bytes[b+i*4+3];
    for(let i=16;i<64;i++) w[i]=(g1(w[i-2])+w[i-7]+g0(w[i-15])+w[i-16])|0;
    let a=H[0],bb=H[1],cc=H[2],dd=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for(let i=0;i<64;i++){
      const t1=(h+s1(e)+ch(e,f,g)+K[i]+w[i])|0;
      const t2=(s0(a)+maj(a,bb,cc))|0;
      h=g;g=f;f=e;e=(dd+t1)|0;dd=cc;cc=bb;bb=a;a=(t1+t2)|0;
    }
    H=[(H[0]+a)|0,(H[1]+bb)|0,(H[2]+cc)|0,(H[3]+dd)|0,(H[4]+e)|0,(H[5]+f)|0,(H[6]+g)|0,(H[7]+h)|0];
  }
  return H.map(x=>((x>>>0).toString(16).padStart(8,'0'))).join('');
}


const previo = $('¿Tomé algo?').first().json;
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const conv = Array.isArray(c) && c.length ? c[0] : null;
const canal = conv && conv.canales ? (Array.isArray(conv.canales) ? conv.canales[0] : conv.canales) : null;

const fallos = [];
if (!conv) fallos.push('no se pudo leer la conversacion');
const clid = conv ? String(conv.ctwa_clid || '') : '';
if (!clid) fallos.push('sin ctwa_clid: el cliente no vino de un anuncio');
const waba = canal ? String(canal.waba_id || '') : '';
if (!waba) fallos.push('el canal de la conversacion no tiene waba_id');

// UNA CONVERSACION = UNA VENTA. La tabla tiene una fila por producto, asi
// que un pedido de dos articulos son dos lineas pero UN evento, sumado.
// Si a UNA sola linea le falta el precio del catalogo NO sale nada: un
// value incompleto es peor que un evento perdido, porque Meta optimiza
// con ese numero y no hay forma de saber que estaba mal.
let valor = 0, unidades = 0;
for (const l of previo.lineas) {
  if (l.precio === null || l.precio === undefined) {
    fallos.push('la linea "' + l.producto + '" no tiene precio del catalogo');
    continue;
  }
  const cant = parseInt(l.cantidad, 10) || 1;
  valor += parseFloat(l.precio) * cant;
  unidades += cant;
}
if (valor <= 0) fallos.push('el importe sale 0');

// event_id ESTABLE: el mismo pedido da siempre el mismo id. Es lo que
// permite reintentar sin contar doble, porque Meta deduplica por event_id.
// Con Date.now() cambiaria en cada intento y la deduplicacion no serviria.
const minId = Math.min.apply(null, previo.ids);
const event_id = 'pedido-' + previo.conversacion_id + '-' + minId;

if (fallos.length) {
  return [{ json: { puede: 'no', motivo: fallos.join(' · '), ids: previo.ids, event_id } }];
}

const evento = {
  data: [{
    event_name: 'Purchase',
    event_time: Math.floor(Date.now() / 1000),
    action_source: 'business_messaging',
    messaging_channel: 'whatsapp',
    event_id: event_id,
    user_data: {
      ctwa_clid: clid,
      whatsapp_business_account_id: waba,
      ph: [sha256(String(conv.cliente_id).replace(/\D/g, '').trim())]
    },
    custom_data: {
      currency: 'MXN',
      value: Math.round(valor * 100) / 100,
      num_items: unidades,
      content_name: previo.lineas.map(function (l) { return l.producto; }).join(' + '),
      order_id: event_id
    }
  }]
};

// El codigo de prueba sale del ENTORNO, no del workflow: se pone en
// wa.env para la primera prueba y se quita despues sin volver a publicar.
if ($env.CAPI_TEST_CODE) evento.test_event_code = $env.CAPI_TEST_CODE;

return [{ json: { puede: 'si', evento, event_id, valor, unidades, ids: previo.ids,
                  canal: canal ? canal.nombre : null, prueba: $env.CAPI_TEST_CODE || null } }];

// neverError esta puesto para poder LEER el cuerpo del rechazo, no para
// tragarselo: aqui se decide explicitamente y el fallo acaba en Telegram
// y en capi_error. Un 4xx de Meta no puede pasar por exito.
const r = $json || {};
const codigo = r.statusCode || 0;
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const prev = $('Construir evento').first().json;
const ok = codigo >= 200 && codigo < 300 && c && c.events_received >= 1;
let motivo = null;
if (!ok) {
  const e = c && c.error;
  motivo = e
    ? ((e.error_user_msg || e.message) + ' (code ' + e.code + (e.error_subcode ? '/' + e.error_subcode : '') + ')')
    : ('respuesta inesperada de Meta, http ' + codigo);
}
return [{ json: { veredicto: ok ? 'si' : 'no', motivo, ids: prev.ids,
  event_id: prev.event_id, valor: prev.valor, unidades: prev.unidades,
  recibidos: c && c.events_received, prueba: prev.prueba } }];

// Un SOLO sitio decide el texto del error, venga de 'no se pudo construir
// el evento' o de un rechazo de Meta. Asi el aviso de Telegram y la
// columna capi_error dicen exactamente lo mismo y no hay que cruzarlos.
const j = $json || {};
return [{ json: {
  ids: j.ids || [],
  motivo: j.motivo || 'motivo desconocido',
  event_id: j.event_id || null,
  origen: j.veredicto === 'no' ? 'Meta lo rechazo' : 'no se pudo construir el evento',
} }];
